package org.sleepwell.app;

import android.app.*;
import android.content.*;
import android.os.*;
import android.view.*;
import android.widget.*;
import java.time.*;
import java.time.format.TextStyle;
import java.util.*;
import java.util.concurrent.*;

/** Board 09 rhythm from saved effective periods, with explicit wake-day classification. */
public final class SleepRhythmActivity extends Activity {
    static java.util.function.LongSupplier clock=System::currentTimeMillis;
    private final ExecutorService reader=Executors.newSingleThreadExecutor();private final Handler handler=new Handler(Looper.getMainLooper());
    private final Runnable observe=this::observeSave;private Records.Factory recordsFactory;private RhythmSettings.Factory settingsFactory;private RhythmStats stats;
    private boolean loaded,resumed,editing,restoredDraft;private int saved=31,draft=31,generation;private String failure="",token;private Dialog dialog;
    @Override public void onCreate(Bundle state){super.onCreate(state);RecordUi.review(this);recordsFactory=Records.factory;settingsFactory=RhythmSettings.factory;if(state!=null){saved=state.getInt("saved",31);draft=state.getInt("draft",31);editing=state.getBoolean("editing");token=state.getString("token");failure=state.getString("failure","");restoredDraft=true;}render();}
    @Override protected void onResume(){super.onResume();resumed=true;load();observeSave();}
    @Override protected void onPause(){resumed=false;handler.removeCallbacks(observe);super.onPause();}
    private void load(){int request=++generation;int cutoff=Math.max(0,Math.min(1439,Prefs.number(this,"statsCutoff",0)));long now=clock.getAsLong();Context app=getApplicationContext();Records.Factory scope=recordsFactory;RhythmSettings.Factory settings=settingsFactory;reader.execute(()->{try(Store store=scope.open(app)){List<RecordEntry> result=Records.all(store);int workdays=RhythmSettings.read(settings.open(app));RhythmStats resultStats=new RhythmStats(result,cutoff,workdays,now);runOnUiThread(()->{if(isDestroyed()||request!=generation)return;stats=resultStats;if(!restoredDraft&&!editing&&token==null){saved=draft=workdays;}restoredDraft=false;loaded=true;if(token==null&&!editing)failure="";render();});}catch(Exception error){runOnUiThread(()->{if(isDestroyed()||request!=generation)return;failure=error.getMessage()==null?"Your sleep records could not be opened.":error.getMessage();loaded=false;render();});}});}
    private void render(){LinearLayout body=Design.page(this,false,null,n->{});RecordUi.header(body,editing?"Your workdays":"Sleep rhythm",this::back);RecordUi.label(this,body);if(!loaded){Design.space(body,24);Design.text(body,failure.isEmpty()?"Loading your nights…":failure,15,400,Design.MUTED);if(!failure.isEmpty())Design.button(body,"Try again",false,this::load);return;}if(editing){workdays(body);return;}
        Design.space(body,10);Design.text(body,"Bedtime range (last 7 nights)",16,600,Design.MUTED);Design.space(body,6);TextView range=Design.text(body,stats.range==null?"—":RecordUi.duration(RhythmStats.displayDurationMillis(stats.range)),52,700,Design.INK);range.setText(RecordUi.units(range.getText().toString()));range.setContentDescription("Bedtime range "+range.getText());Design.text(body,stats.recent.isEmpty()?"No main nights yet":stats.range==null?"One night · add another to compare.":"Your bedtime varied by "+Math.round(stats.range)+" minutes.",13,400,Design.MUTED);
        if(stats.recent.isEmpty()){Design.space(body,30);Design.text(body,"Your rhythm starts with a night",20,600,Design.INK);Design.space(body,8);Design.text(body,"Closed main sleep periods appear here. Missing nights stay blank.",14,400,Design.MUTED);Design.space(body,30);}else{Design.space(body,12);body.addView(new RhythmChart(this,stats.recent,SleepPlans.load(this).bedtime),new LinearLayout.LayoutParams(-1,Design.dp(this,240)));}
        Design.space(body,14);Design.line(body);Design.space(body,12);heading(body,"Social jetlag","About social jetlag",()->message("Social jetlag","This is the shortest clock-time difference between the average recorded period midpoint on your selected workdays and free days, using the displayed nights. Workdays are classified by the local calendar date you woke up, including daylight-saving changes. It is a descriptive timing comparison, not a diagnosis or a measured body-clock phase."));
        LinearLayout row=Design.row(this),metric=Design.col(this),groups=Design.col(this);TextView gap=Design.text(metric,stats.jetlag==null?"—":RecordUi.duration(RhythmStats.displayGapMillis(stats.workMidpoint,stats.freeMidpoint)),38,700,Design.INK);gap.setText(RecordUi.units(gap.getText().toString()));gap.setContentDescription("Social jetlag "+gap.getText());Design.text(metric,stats.jetlag==null?"Need workday and free-day nights.":"Difference in recorded mid-sleep.",12,400,Design.MUTED);row.addView(metric,new LinearLayout.LayoutParams(0,-2,1));View divider=new View(this);divider.setBackgroundColor(Design.LINE);LinearLayout.LayoutParams line=new LinearLayout.LayoutParams(Design.dp(this,1),Design.dp(this,76));line.setMargins(Design.dp(this,12),0,Design.dp(this,12),0);row.addView(divider,line);group(groups,"Workdays",stats.workCount,stats.workMidpoint,Design.VIOLET);Design.space(groups,9);group(groups,"Free days",stats.freeCount,stats.freeMidpoint,Design.BROWN);row.addView(groups,new LinearLayout.LayoutParams(0,-2,.85f));body.addView(row);
        Design.space(body,16);Design.line(body);PlanActivity.detail(body,"report","Sleep timing groups","Compare recorded midpoints across 90 days",null,()->startActivity(RecordUi.intent(this,RhythmGroupsActivity.class)));
        Design.space(body,18);Design.line(body);Design.space(body,10);heading(body,"Chronotype","About chronotype evidence",()->message("Chronotype evidence","Thirty distinct phone-recorded main nights is a history target from the design, not a validated cutoff. Manual periods help describe timing but do not count as phone recordings. SleepWell has not assessed alarm-free sleep, sleep-onset latency or recovery sleep, so it does not assign a clinical chronotype or an owl/lark category from these records."));Design.space(body,2);Design.text(body,stats.recorded<30?stats.recorded+" of 30 nights":stats.recorded+" nights recorded",23,600,Design.INK);Design.text(body,stats.recorded<30?"More recorded nights needed":"History target reached",13,400,Design.MUTED);Design.space(body,7);progress(body,stats.recorded);Design.space(body,6);Design.text(body,"History progress · chronotype is not assessed.",11,400,Design.MUTED);Design.space(body,12);PlanActivity.detail(body,"calendar","Workday schedule","Classify nights by wake-up day",summary(saved),()->{draft=saved;editing=true;failure="";render();});Design.line(body);PlanActivity.detail(body,"info","About these records",null,null,()->message("Recorded periods","The latest seven available main nights are shown with their dates. Each sleep-day uses its longest closed, untagged-nap period of at least three recorded hours, matching History. Pauses and awake edits are excluded from coverage; edge edits trim the plotted period. Manual periods are user-reported. Bedtime range uses the shortest interval around the 24-hour clock. Midpoints use elapsed time between the effective period boundaries, not sleep-stage estimates."));
    }
    private void heading(LinearLayout body,String text,String description,Runnable action){LinearLayout row=Design.row(this);row.addView(Design.text(this,text,16,600,Design.INK),new LinearLayout.LayoutParams(-2,-2));View info=Design.iconButton(this,"info",description,action);row.addView(info,new LinearLayout.LayoutParams(Design.dp(this,40),Design.dp(this,40)));body.addView(row);}
    private void group(LinearLayout col,String text,int count,Double mean,int color){Design.text(col,"●  "+text+" ("+count+")",11,400,color);Design.text(col,mean==null?"—":RhythmChart.label(this,mean),16,600,Design.INK);}
    private void progress(LinearLayout body,int nights){FrameLayout track=new FrameLayout(this);track.setBackground(Design.shape(this,0xffeee0d4,12));View fill=new View(this);fill.setBackground(Design.shape(this,Design.VIOLET,12));track.addView(fill,new FrameLayout.LayoutParams(0,-1));track.setContentDescription("Recorded-night history progress "+nights+" of 30");track.addOnLayoutChangeListener((v,a,b,c,d,e,f,g,h)->{ViewGroup.LayoutParams p=fill.getLayoutParams();int width=Math.round(track.getWidth()*Math.min(30,nights)/30f);if(p.width!=width){p.width=width;fill.setLayoutParams(p);}});body.addView(track,new LinearLayout.LayoutParams(-1,Design.dp(this,12)));}
    private void workdays(LinearLayout body){Design.space(body,12);Design.text(body,"Choose the days you wake for work or school.",14,400,Design.MUTED);Design.space(body,10);for(int day=1;day<=7;day++){int bit=1<<(day-1);Design.toggle(body,DayOfWeek.of(day).getDisplayName(TextStyle.FULL,Locale.getDefault()),null,(draft&bit)!=0,on->{if(on)draft|=bit;else draft&=~bit;});Design.line(body);}Design.space(body,10);Design.text(body,"Unselected days are free days. A fixed weekly schedule may not describe shift work.",12,400,Design.MUTED);if(!failure.isEmpty())Design.text(body,failure,13,500,0xffa93919);Design.button(RecordUi.footer(body),token==null?"Save workdays":"Saving…",true,this::save);if(token!=null)RecordUi.enabled(body,false);}
    private String summary(int mask){if(mask==0)return "No workdays";if(mask==127)return "Every day";List<String> days=new ArrayList<>();for(int n=1;n<=7;n++)if((mask&(1<<(n-1)))!=0)days.add(DayOfWeek.of(n).getDisplayName(TextStyle.NARROW,Locale.getDefault()));return String.join(" · ",days);}
    private void message(String title,String text){if(dialog!=null&&dialog.isShowing())return;dialog=SleepPicker.message(this,title,text);}
    private void save(){if(token!=null)return;token=UUID.randomUUID().toString();failure="";render();observeSave();}
    private void observeSave(){if(!resumed||token==null)return;int value=draft,expected=saved;RhythmSettings.Factory scope=settingsFactory;PlanOperations.Operation operation=PlanOperations.start(this,token,app->{RhythmSettings.save(scope.open(app),value,expected);return null;});if(!operation.done){handler.postDelayed(observe,75);return;}PlanOperations.forget(token);token=null;if(operation.error==null){saved=draft;editing=false;failure="";loaded=false;load();}else failure=operation.error;render();}
    private void back(){if(token!=null)return;if(editing){draft=saved;editing=false;failure="";loaded=false;load();render();}else finish();}
    @android.annotation.SuppressLint("GestureBackNavigation") @Override public void onBackPressed(){back();}
    @Override protected void onSaveInstanceState(Bundle state){super.onSaveInstanceState(state);state.putInt("saved",saved);state.putInt("draft",draft);state.putBoolean("editing",editing);state.putString("token",token);state.putString("failure",failure);}
    @Override public void onWindowFocusChanged(boolean focused){super.onWindowFocusChanged(focused);if(focused)RecordUi.lightBars(this);}
    void awaitReaders(long timeout)throws Exception{if(reader.isShutdown()){if(!reader.awaitTermination(timeout,TimeUnit.MILLISECONDS))throw new TimeoutException("Rhythm readers still active");}else reader.submit(()->{}).get(timeout,TimeUnit.MILLISECONDS);}
    @Override protected void onDestroy(){generation++;handler.removeCallbacksAndMessages(null);if(dialog!=null)dialog.dismiss();reader.shutdownNow();super.onDestroy();}
}
